export function buildSetupRail(input: SetupRailInput): SetupRailState {
  const tasks: SetupTask[] = input.services.map((s) => ({
    id: `service:${s.serviceId}`,
    title: s.title,
    href: s.href,
    done: isServiceComplete(input.onboardingSteps, s.serviceId),
    serviceId: s.serviceId,
    hardGated: s.hardGated,
  }))
  if (input.isAdmin && input.welcome) {
    tasks.push(
      { id: 'billing', title: 'Finish billing', href: '/app/settings', done: input.welcome.billingActive },
      { id: 'invites', title: 'Invite your team', href: '/app/settings', done: input.welcome.invitesSent > 0 },
    )
  }
  const total = tasks.length
  const done = tasks.filter((t) => t.done).length
  const next = tasks.find((t) => !t.done) ?? null
  const hidden =
    input.onboardingSteps === null ||
    total === 0 ||
    done === total ||
    (!input.forceShow && (input.quiet || input.dismissed))
  return {
    visible: !hidden,
    total,
    done,
    pct: total > 0 ? Math.round((done / total) * 100) : 0,
    tasks,
    next,
  }
}

