// Every Pace host a landing page names anywhere (text, scripts, JSON-LD) must
// be a manifest host, so a retired or invented host cannot hide in copy.
func TestLandingPaceHostsAreInManifest(t *testing.T) {
	_, hosts := loadManifest(t)
	files := landingPages(t)
	for _, extra := range []string{"scripts/status.js", "live-demo-embed.js", "demo-vars.js", "waitlist.js"} {
		files = append(files, filepath.Join(landingDir, extra))
	}
	for _, f := range files {
		b, err := os.ReadFile(f)
		if err != nil {
			t.Fatal(err)
		}
		for _, mm := range reHost.FindAllStringSubmatch(string(b), -1) {
			h := strings.ToLower(strings.TrimRight(mm[1], "."))
			if rePaceDN.MatchString(h) && !hosts[h] {
				t.Errorf("%s names %s, which is not in tests/live/hosts.manifest.json", f, h)
			}
		}
	}
}

func TestDemoLoadsItsScripts(t *testing.T) {
	b, err := os.ReadFile(filepath.Join(landingDir, "demo.html"))
	if err != nil {
		t.Fatal(err)
	}
	demo := string(b)
	if !strings.Contains(demo, `<script src="demo-vars.js"></script>`) {
		t.Error("demo.html must load demo-vars.js")
	}
	// demo.html does not load live-demo-embed.js: the generator
	// (landing/scripts/build-live-demo-embed.py, regenerated in CI) inlines the
	// same script under its unprefixed names (nav for paceDemoNav, ...), and
	// live-demo-embed.js is the paceDemo-prefixed copy for embedding. So demo.html
	// carries the embed's behavior when every embed function exists inline.
	emb, err := os.ReadFile(filepath.Join(landingDir, "live-demo-embed.js"))
	if err != nil {
		t.Fatal(err)
	}
	funcs := regexp.MustCompile(`(?m)^function paceDemo(\w+)`).FindAllStringSubmatch(string(emb), -1)
	if len(funcs) == 0 {
		t.Fatal("live-demo-embed.js defines no paceDemo functions")
	}
	for _, fn := range funcs {
		name := strings.ToLower(fn[1][:1]) + fn[1][1:]
		if !strings.Contains(demo, "function "+name+"(") {
			t.Errorf("demo.html does not define %s (the inline form of paceDemo%s)", name, fn[1])
		}
	}
}

