func TestProbeFailsOnBrokenSite(t *testing.T) {
	rs := run(t, func(w http.ResponseWriter, r *http.Request) {
		switch {
		case r.URL.Path == "/demo":
			http.NotFound(w, r)
		case r.URL.Path == "/legal/terms":
			http.Redirect(w, r, "/terms", http.StatusFound) // 302, not 301
		case r.URL.Path == "/legal/privacy":
			http.Redirect(w, r, "/elsewhere", http.StatusMovedPermanently)
		case r.URL.Path == "/robots.txt":
			w.Write([]byte("User-agent: *\n"))
		default:
			good(w, r)
		}
	})
	joined := strings.Join(fails(rs), "\n")
	for _, want := range []string{"/demo http", "/legal/terms http", "/legal/privacy http", "/robots.txt http"} {
		if !strings.Contains(joined, want) {
			t.Errorf("expected a FAIL for %q in:\n%s", want, joined)
		}
	}
}
