async function main() {
  const remote = process.argv.includes("--remote");
  const sqlPath = path.join(process.cwd(), "seed", "places.sql");

  // getPlatformProxy only proxies bindings marked `remote: true`, so for
  // --remote write a temporary config that flags the DB binding as remote
  // (keeps `wrangler dev` / local seed on the local D1).
  let configPath = "./wrangler.jsonc";
  const tmpConfig = path.join(process.cwd(), "wrangler.seed-remote.jsonc");
  if (remote) {
    const base = fs.readFileSync(configPath, "utf8");
    const patched = base.replace(/"binding":\s*"DB",/, '"binding": "DB",\n      "remote": true,');
    if (patched === base) throw new Error("Could not mark DB binding remote");
    fs.writeFileSync(tmpConfig, patched);
    configPath = tmpConfig;
  }

  const proxy = await getPlatformProxy<CloudflareEnv>({
    configPath,
    remoteBindings: remote,
  });
  if (remote) fs.rmSync(tmpConfig, { force: true });

  const d1 = proxy.env.DB;
  if (!d1) {
    throw new Error("D1 binding DB missing from wrangler.jsonc");
  }

  const db = drizzle(d1, { schema });
  await seedInitial(db);

  if (fs.existsSync(sqlPath)) {
    const flag = remote ? "--remote" : "--local";
    execSync(`npx wrangler d1 execute kate ${flag} --file=${sqlPath}`, {
      stdio: "inherit",
      cwd: process.cwd(),
    });
  } else {
    console.warn("seed/places.sql missing — run npm run places:build");
  }

  await tagRockCanyonPlaces(db);
  await proxy.dispose();
