import { NextResponse } from "next/server";

import { getAppApiToken } from "../env";

/** True when the request carries a valid app bearer token. False when unconfigured. */
export function hasAppAuth(request: Request): boolean {
  const expected = getAppApiToken();
  if (!expected) {
    return false;
  }
  const header = request.headers.get("authorization");
  const token = header?.startsWith("Bearer ") ? header.slice(7) : null;
  return token === expected;
}

/** Bearer guard for /api/v1 routes; returns the denial response, or null when authorized. */
export function requireAppAuth(request: Request): NextResponse | null {
  const expected = getAppApiToken();
  if (!expected) {
    return NextResponse.json(
      { error: "KATE_APP_TOKEN is not configured on the server" },
      { status: 503 },
    );
  }
  if (!hasAppAuth(request)) {
    return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
  }
  return null;
}
