  listVisibleJournal,
  listVisibleMovies,
  listVisibleProposals,
  listVisibleTodos,
  listVisibleTravelPlaces,
  listVisibleTrips,
  moviesWatchedThisYear,
} from "../../modules/queries";
import { getUserNames } from "../env";
import { tagsFromJson } from "../tags";

function parseJsonValue(raw: string | null | undefined): unknown {
  if (!raw) {
    return null;
  }
  try {
    return JSON.parse(raw);
  } catch {
    return null;
  }
}

function parseStringArray(raw: string | null | undefined): string[] {
  const value = parseJsonValue(raw);
  return Array.isArray(value) ? value.filter((v) => typeof v === "string") : [];
}

export async function readJournal(db: Database) {
  const [entries, links, activities, mediaByEntry] = await Promise.all([
    listVisibleJournal(db),
    db.select().from(journalLinks),
    listVisibleActivities(db),
    listMediaByJournal(db),
  ]);
  const linksByEntry = new Map<string, { entityType: string; entityId: string }[]>();
  for (const l of links) {
    const list = linksByEntry.get(l.journalId) ?? [];
    list.push({ entityType: l.entityType, entityId: l.entityId });
    linksByEntry.set(l.journalId, list);
  }
  return {
    entries: entries.map((e) => ({
      ...e,
      tags: tagsFromJson(e.tags),
      links: linksByEntry.get(e.id) ?? [],
      media: (mediaByEntry.get(e.id) ?? []).map((m) => ({
        id: m.id,
        url: `/api/media/${m.id}`,
        contentType: m.contentType,
        caption: m.caption,
        addedBy: m.addedBy,
      })),
    })),
    activities,
  };
}

export async function readMovies(db: Database) {
  const [movieRows, watchDates, watchedThisYear] = await Promise.all([
    listVisibleMovies(db),
    listMovieWatchDates(db),
    moviesWatchedThisYear(db),
  ]);
  return { movies: movieRows, watchDates, watchedThisYear };
}

export async function readTodos(db: Database) {
  const [todoRows, logs] = await Promise.all([listVisibleTodos(db), listTodoLogs(db)]);
  return {
    todos: todoRows.map((t) => ({ ...t, labels: parseStringArray(t.labels) })),
    logs,
  };
}

export async function readCamping(db: Database) {
  const [trips, visits] = await Promise.all([listVisibleTrips(db), listCampingVisits(db)]);
  return { trips, visits };
}

export async function readTravel(db: Database) {
  const [places, countriesVisited] = await Promise.all([
    listVisibleTravelPlaces(db),
    countCountriesVisited(db),
  ]);
  return { places, countriesVisited };
}

export async function readMap(db: Database) {
  return { pins: await listMapPins(db) };
}

export async function readPlans(db: Database) {
  const [proposalRows, busy] = await Promise.all([
    listVisibleProposals(db),
    listVisibleBusyBlocks(db),
  ]);
  return {
    proposals: proposalRows,
    busyBlocks: busy,
    users: getUserNames(),
  };
}

export async function readReview(db: Database) {
  const pending = await listPendingReview(db);
  return {
    pending: pending.map((item) => ({
      id: item.id,
