/**
 * Dispatch a `{action, params}` envelope to the shared mutation layer.
 * Throws Error("Unknown action: …") for unlisted names; ZodError surfaces param problems.
 */
export async function runAppAction(db: Database, raw: unknown): Promise<unknown> {
  const { action, params } = envelopeSchema.parse(raw);
  const defn = appActions[action];
  if (!defn) {
    throw new Error(`Unknown action: ${action}`);
  }
  return defn.run(db, defn.schema.parse(params));
}
