import { createRemoteJWKSet, jwtVerify, type JWTVerifyGetKey } from "jose";

import { sha256Hex } from "./crypto";

export const APPLE_ISSUER = "https://appleid.apple.com";
export const APPLE_JWKS_URL = "https://appleid.apple.com/auth/keys";
export const DEFAULT_APPLE_BUNDLE_ID = "com.duketopceo.kate";

export function getAppleBundleId(): string {
  return process.env.APPLE_BUNDLE_ID?.trim() || DEFAULT_APPLE_BUNDLE_ID;
}

let remoteJwks: JWTVerifyGetKey | undefined;
function defaultJwks(): JWTVerifyGetKey {
  remoteJwks ??= createRemoteJWKSet(new URL(APPLE_JWKS_URL));
  return remoteJwks;
}

export type AppleIdentity = { subject: string };

export type VerifyAppleOptions = {
  /** Injectable key set (tests use a local JWKS). */
  jwks?: JWTVerifyGetKey;
  audience?: string;
};

/** Verifies an Apple identity token; returns the Apple `sub` or null on any failure. */
export async function verifyAppleIdentityToken(
  identityToken: string,
  rawNonce: string,
  options: VerifyAppleOptions = {},
): Promise<AppleIdentity | null> {
  try {
    const { payload } = await jwtVerify(identityToken, options.jwks ?? defaultJwks(), {
      issuer: APPLE_ISSUER,
      audience: options.audience ?? getAppleBundleId(),
      algorithms: ["RS256"],
    });
    if (typeof payload.sub !== "string" || !payload.sub) {
      return null;
    }
    if (typeof payload.nonce !== "string" || payload.nonce !== (await sha256Hex(rawNonce))) {
      return null;
    }
    return { subject: payload.sub };
  } catch {
    return null;
  }
}
