export const MAX_USERS = 4;

export const appleSignInBody = z.object({
  identityToken: z.string().min(1),
  nonce: z.string().min(1),
  fullName: z
    .object({
      givenName: z.string().nullish(),
      familyName: z.string().nullish(),
    })
    .nullish(),
  signupCode: z.string().nullish(),
});

export type SignInResult =
  | { status: 200; body: { ok: true; result: { sessionToken: string; user: PublicUser } } }
  | { status: 400 | 401 | 403 | 503; body: { ok: false; error: string } };

export type PublicUser = { id: string; displayName: string | null };

function fail(status: 400 | 401 | 403 | 503, error: string): SignInResult {
  return { status, body: { ok: false, error } };
}

function displayNameFrom(
  fullName: z.infer<typeof appleSignInBody>["fullName"],
): string | null {
  const name = [fullName?.givenName, fullName?.familyName]
    .map((s) => s?.trim())
    .filter(Boolean)
    .join(" ");
  return name || null;
}

export async function signInWithApple(
  db: Database,
  rawBody: unknown,
  options: { jwks?: JWTVerifyGetKey } = {},
): Promise<SignInResult> {
  const parsed = appleSignInBody.safeParse(rawBody);
  if (!parsed.success) {
    return fail(400, "bad_request");
  }
  const body = parsed.data;

  const total = (await db.select().from(users)).length; // household is capped at a handful of rows
  const signupSecret = process.env.KATE_SIGNUP_CODE;
  if (!signupSecret && total === 0) {
    return fail(503, "auth_not_configured");
  }

  const identity = await verifyAppleIdentityToken(body.identityToken, body.nonce, {
    jwks: options.jwks,
  });
  if (!identity) {
    return fail(401, "invalid_apple_token");
  }

  const existing = await db
    .select()
    .from(authIdentities)
    .innerJoin(users, eq(users.id, authIdentities.userId))
    .where(and(eq(authIdentities.provider, "apple"), eq(authIdentities.subject, identity.subject)))
    .limit(1);

  if (existing[0]) {
    let user = existing[0].users;
    const name = displayNameFrom(body.fullName);
    if (!user.displayName && name) {
      await db.update(users).set({ displayName: name }).where(eq(users.id, user.id));
      user = { ...user, displayName: name };
    }
    const sessionToken = await createSession(db, user.id);
    return {
      status: 200,
      body: { ok: true, result: { sessionToken, user: { id: user.id, displayName: user.displayName } } },
    };
  }

  if (!signupSecret || !body.signupCode || !(await safeEqual(body.signupCode, signupSecret))) {
    return fail(403, "signup_code_required");
  }
  if (total >= MAX_USERS) {
    return fail(403, "household_full");
  }

  const userId = newId();
  const ts = nowIso();
  const displayName = displayNameFrom(body.fullName);
  await db.insert(users).values({ id: userId, displayName, createdAt: ts });
  await db.insert(authIdentities).values({
    id: newId(),
    userId,
    provider: "apple",
    subject: identity.subject,
    createdAt: ts,
  });
  const sessionToken = await createSession(db, userId);
  return {
    status: 200,
    body: { ok: true, result: { sessionToken, user: { id: userId, displayName } } },
  };
}
