export const dynamic = "force-dynamic";

// Binary reads are unauthenticated but addressed by unguessable media ids,
// matching the app's open-read posture and enabling <img>/AsyncImage use.
export async function GET(
  _request: Request,
  { params }: { params: Promise<{ id: string }> },
) {
  const { id } = await params;
  const db = await getDb();
  const rows = await db
    .select()
    .from(media)
    .where(and(eq(media.id, id), eq(media.hidden, false)));
  const row = rows[0];
  if (!row) {
    return NextResponse.json({ error: "Not found" }, { status: 404 });
  }

  const object = await (await getMediaBucket()).get(row.r2Key);
  if (!object) {
    return NextResponse.json({ error: "Not found" }, { status: 404 });
  }

  return new Response(object.body, {
    headers: {
      "content-type": row.contentType,
      "cache-control": "private, max-age=31536000, immutable",
      "content-length": String(row.sizeBytes),
    },
  });
}
