public enum UploadPolicy {
    public static let fullChunk = TrackChunker.defaultMaxPoints
    /// On Wi-Fi or charging, anything buffered this long goes even if it is a short chunk.
    public static let cheapAge: TimeInterval = 10 * 60
    /// On cellular and battery, data this old goes (one small request) unless Low Power Mode is on.
    public static let cellularFallbackAge: TimeInterval = 30 * 60

    /// When this says yes the uploader sends everything buffered, including a short tail.
    /// Points are safe on disk meanwhile, so waiting costs nothing but freshness.
    public static func shouldUpload(pending: Int, oldestAge: TimeInterval, conditions c: UploadConditions,
                                    outingEnded: Bool = false) -> Bool {
        guard pending > 0 else { return false }
        let cheap = c.onWiFi || c.charging
        if outingEnded { return cheap || !c.lowPowerMode || oldestAge >= cellularFallbackAge }
        if cheap { return pending >= fullChunk || oldestAge >= cheapAge }
        if c.lowPowerMode { return false }
        return oldestAge >= cellularFallbackAge
    }
}
