import { getMediaBucket } from "@/lib/media";
import { DEFAULT_CAPTURE_ZONE } from "@/lib/media-upload";
import { backfillWhen } from "@/lib/when/backfill";

export const dynamic = "force-dynamic";

/**
 * Admin backfill of "when it happened": reads each attached JPEG's EXIF capture time into media.captured_at and
 * dates entries that have no event time from min/max of their photos (source 'photos'). Legacy app token only
 * (operator action; the original crew, or `crewId=`). POST ?limit=25&cursor=<id>&zone=America/Denver; repeat with
 * cursor=nextCursor until it is null. Not run automatically.
 */
async function postHandler(request: Request) {
  if (!hasAppAuth(request)) return unauthorized();
  const sp = new URL(request.url).searchParams;
  const limit = Math.min(100, Math.max(1, Number.parseInt(sp.get("limit") ?? "25", 10) || 25));
  const zone = sp.get("zone") || DEFAULT_CAPTURE_ZONE;
  try {
    new Intl.DateTimeFormat("en-US", { timeZone: zone });
  } catch {
    return NextResponse.json({ ok: false, error: "bad_request", message: "unknown time zone" }, { status: 400 });
  }
  const db = await getDb();
  const result = await backfillWhen(db, sp.get("crewId") || DEFAULT_CREW_ID, await getMediaBucket(), {
    limit,
    cursor: sp.get("cursor"),
    zone,
  });
  return NextResponse.json({ ok: true, ...result });
}

export const POST = withApiErrors(postHandler);
