{
  "$schema": "../../node_modules/wrangler/config-schema.json",
  // The kate-mcp Worker: OAuth 2.1 authorization server + stateless MCP endpoint for AI assistants.
  // Separate from the `kate` (OpenNext) Worker so its bundle and deploy blast radius stay small.
  // Deploy (after the checklist in docs/mcp.md): npx wrangler deploy -c workers/kate-mcp/wrangler.jsonc
  "name": "kate-mcp",
  "main": "src/index.ts",
  "compatibility_date": "2025-03-01",
  // global_fetch_strictly_public is required by the OAuth provider's Client ID Metadata Document fetches.
  "compatibility_flags": ["nodejs_compat", "global_fetch_strictly_public"],
  // No second public origin: /register, /token, /authorize and /mcp are reachable only on the custom domain (where the WAF rules live).
  "workers_dev": false,
  "routes": [{ "pattern": "mcp.kate.luke-the-duke.com", "custom_domain": true }],
  // TO CREATE BEFORE DEPLOY: `npx wrangler kv namespace create OAUTH_KV`, then paste the id here.
  "kv_namespaces": [{ "binding": "OAUTH_KV", "id": "REPLACE_WITH_OAUTH_KV_NAMESPACE_ID" }],
  // Deliberately NO d1_databases and NO r2_buckets (security review 2026-10-13, M3). Pending consents, grants, audit and
  // rate limits all live in the Kate Worker's D1 and are reached through the service binding below, so a bug here cannot
  // run a raw query against the journal. The only state kate-mcp owns is the OAuth provider's KV (clients, codes, tokens).
  // Tool calls run inside the `kate` Worker so crew scoping and write rules live in one place.
  "services": [{ "binding": "KATE", "service": "kate" }],
  "vars": { "KATE_ORIGIN": "https://kate.luke-the-duke.com" }
