export function cleanScopes(values: unknown): Scope[] {
  if (!Array.isArray(values)) return [];
  return [...new Set(values.filter((v): v is Scope => typeof v === "string" && isScope(v)))];
}

/** A real calendar date: "2026-02-30" and "9999-99-99" are rejected (a regex alone let them through to a 500). */
export function isRealDate(s: string): boolean {
  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(s);
  if (!m) return false;
  const d = new Date(Date.UTC(Number(m[1]), Number(m[2]) - 1, Number(m[3])));
  return d.getUTCFullYear() === Number(m[1]) && d.getUTCMonth() === Number(m[2]) - 1 && d.getUTCDate() === Number(m[3]);
}

const day = z.string().refine(isRealDate, "date must be a real date, YYYY-MM-DD");

