    public static func cluster(media: [MediaMoment], health: [HealthBucket], routes: [RouteSegment],
                               config: OutingConfig = OutingConfig()) -> [Outing] {
        let routes = dedupe(routes: routes, config: config)
        let health = health.filter { $0.steps >= config.minBucketSteps || $0.flights >= 1 }

        var anchors: [Anchor] = []
        for m in media { anchors.append(Anchor(start: m.time, end: m.time, first: m.coordinate, last: m.coordinate)) }
        for h in health { anchors.append(Anchor(start: h.start, end: h.end, first: nil, last: nil)) }
        for r in routes {
            guard let s = r.start, let e = r.end else { continue }
            anchors.append(Anchor(start: s, end: e, first: r.points.first?.coordinate, last: r.points.last?.coordinate))
        }
        anchors.sort { $0.start < $1.start }

        // Group anchors.
        var groups: [[Anchor]] = []
        var groupEnd = Date.distantPast
        var lastLocated: (coord: Coordinate, time: Date)?
        for a in anchors {
            let gap = a.start.timeIntervalSince(groupEnd)
            var split = groups.isEmpty || gap > config.maxGap
            if !split, let ll = lastLocated, let c = a.first {
                let d = Geo.distance(ll.coord, c)
                let dt = max(1, a.start.timeIntervalSince(ll.time))
                if d > config.jumpDistance && d / dt > config.jumpSpeed { split = true }
            }
            if split {
                groups.append([a])
                lastLocated = nil
                groupEnd = a.end
            } else {
                groups[groups.count - 1].append(a)
                groupEnd = max(groupEnd, a.end)
            }
            if let l = a.last { lastLocated = (l, a.end) }
        }

        // Fill each group.
        var outings: [Outing] = []
        for g in groups {
            let start = g.map(\.start).min()!
            let end = g.map(\.end).max()!
            func inside(_ t: Date) -> Bool { t >= start && t <= end }
            let m = media.filter { inside($0.time) }.sorted { $0.time < $1.time }
            let h = health.filter { $0.start >= start && $0.end <= end || inside($0.start) }
            let r = routes.filter { ($0.start.map(inside) ?? false) }
            let route = r.flatMap(\.points).sorted { $0.time < $1.time }
            let steps = h.reduce(0) { $0 + $1.steps }
            let flights = h.reduce(0) { $0 + $1.flights }
            let healthMeters = h.reduce(0) { $0 + $1.meters }

            // Skip outings that are only a trickle of steps.
            if m.isEmpty && r.isEmpty && steps < config.minStepsAlone { continue }

            var dist = 0.0
            for seg in r { dist += Geo.pathLength(seg.points) }
            if r.isEmpty { dist = healthMeters }

            var gain: Double?
            var fromFlights = false
            let altitudePoints = r.flatMap(\.points).sorted { $0.time < $1.time }
            if let s = Elevation.stats(altitudePoints) {
                gain = s.gain
            } else if flights > 0 {
                gain = Elevation.gain(fromFlights: flights)
                fromFlights = true
            }

            var coords = route.map(\.coordinate)
            if coords.isEmpty { coords = m.compactMap(\.coordinate) }
            var sources = Set<String>()
            if !m.isEmpty { sources.insert("media") }
            if !h.isEmpty { sources.insert("health") }
            for seg in r { sources.insert(seg.source.rawValue) }

            outings.append(Outing(
                id: "o-\(Int(start.timeIntervalSince1970))",
                start: start, end: end,
                centroid: Geo.centroid(coords),
                media: m, steps: steps, distanceMeters: dist,
                elevationGain: gain, elevationFromFlights: fromFlights, flights: flights,
                route: route, sources: sources
            ))
        }
        return outings
