    if (!finalCards.length && !finalQuiz.length) {
      await setProgress(deps, set, { gateJson: JSON.stringify(gate) }, "failed", 0, "failed");
      await fail(deps, set, "no_items_passed_gate");
      return { ran: true, status: "failed", cursor, total: groups.length };
    }
    await setProgress(deps, set, { genStatus: "ready", genStage: "done", genError: null, gateJson: JSON.stringify({ ...gate, applyShare: finalQuiz.length ? finalQuiz.filter((x) => x.apply).length / finalQuiz.length : 0 }), leaseUntil: null }, "ready", 1, "done");
    return { ran: true, status: "ready", cursor, total: groups.length };
  } catch (err) {
    console.error("[study] advanceSet failed", err);
    set = (await get()) ?? set;
    await fail(deps, set, "pipeline_error");
    return { ran: true, status: "failed", cursor: set.genCursor, total: set.genTotal };
  }
}

/** Fire-and-forget kick (POST, and every status poll while a set is unfinished). */
export function kickSet(deps: StudyDeps, accountId: string, setId: string): void {
  deps.waitUntil(advanceSet(deps, accountId, setId).catch((e) => console.error("[study] kick failed", e)));
}

