    /// The more restrictive of two bands (the younger one).
    public static func stricter(_ a: AgeBand, _ b: AgeBand?) -> AgeBand {
        guard let b else { return a }
        return b.rank < a.rank ? b : a
    }

    /// Band for a birth month and year, as of `today` (UTC). The birth month counts as ending on its
    /// last day, so a person turns 13 on the last day of their birth month. Nil for a month outside
    /// 1...12, an implausible year, or a month after the current one.
    public static func from(month: Int, year: Int, today: Date) -> AgeBand? {
        guard (1...12).contains(month), year >= 1900 else { return nil }
        var cal = Calendar(identifier: .gregorian)
        cal.timeZone = TimeZone(identifier: "UTC") ?? .gmt
        let now = cal.dateComponents([.year, .month, .day], from: today)
        guard let ty = now.year, let tm = now.month, let td = now.day else { return nil }
        if (year, month) > (ty, tm) { return nil }
        guard let monthStart = cal.date(from: DateComponents(year: year, month: month, day: 1)),
              let lastDay = cal.range(of: .day, in: .month, for: monthStart)?.count else { return nil }
        var age = ty - year
        if (tm, td) < (month, lastDay) { age -= 1 }
        if age < minimumAge { return .under13 }
        return age < adultAge ? .teen : .adult
    }

    /// Band implied by a Declared Age Range answer (lower and upper bound in years, either may be nil).
    /// Nil when the answer does not pin a band down.
    public static func fromDeclared(lowerBound: Int?, upperBound: Int?) -> AgeBand? {
        if let upper = upperBound, upper < minimumAge { return .under13 }
        if let lower = lowerBound, lower >= adultAge { return .adult }
        if let upper = upperBound, upper < adultAge, upper >= minimumAge { return .teen }
        return nil
    }
