export const AGE_BANDS = ["under13", "13-17", "18+"] as const;
export type AgeBand = (typeof AGE_BANDS)[number];
/** Bands an account can be created with (the floor is 13, `MIN_AGE`). */
export type AccountAgeBand = Exclude<AgeBand, "under13">;

export type AgeGate =
  | { ok: true; ageBand: AccountAgeBand }
  | { ok: false; error: "age_not_eligible" | "age_confirmation_required" | "bad_request" };

function isAgeBand(s: string): s is AccountAgeBand {
  return (AGE_BANDS as readonly string[]).includes(s) && s !== "under13";
}

