#!/usr/bin/env bash
# Apply every migration to a brand-new local D1 with wrangler (workerd's real D1 SQL engine, not libsql), so
# D1-only limits fail here instead of in production (0043 shipped a 9-term compound SELECT; D1 caps at 5).
# Usage: scripts/test/d1-migrations-check.sh [--migrations-dir DIR]
# Local only: never touches a remote database. State lives in a throwaway temp dir.
set -euo pipefail
cd "$(dirname "$0")/../.."
root=$(pwd)

dir="$root/drizzle/migrations"
while [ $# -gt 0 ]; do
  case "$1" in
    --migrations-dir) dir=$(cd "$2" && pwd); shift ;;
    *) echo "unknown option: $1" >&2; exit 2 ;;
  esac
  shift
done

work=$(mktemp -d)
trap 'rm -rf "$work"' EXIT
cat >"$work/wrangler.jsonc" <<JSON
{
  "name": "kate-migrations-check",
  "compatibility_date": "2025-03-01",
  "d1_databases": [
    { "binding": "DB", "database_name": "kate", "database_id": "00000000-0000-0000-0000-000000000000", "migrations_dir": "$dir" }
  ]
}
JSON

if ! out=$(npx --no-install wrangler d1 migrations apply DB --local -c "$work/wrangler.jsonc" --persist-to "$work/state" 2>&1); then
  echo "$out" >&2
  echo "d1-migrations-check: FAILED (a migration does not apply on D1's SQL engine)" >&2
  exit 1
fi
count=$(find "$dir" -maxdepth 1 -name '*.sql' | wc -l | tr -d ' ')
echo "d1-migrations-check: OK ($count migration files applied to a fresh local D1)"
