set -euo pipefail
cd "$(dirname "$0")/../.."
port="${1:-8788}"
if [ ! -f .open-next/worker.js ] || [ "${E2E_REBUILD:-}" = "1" ]; then
  npm run build:cloudflare
fi
npx --no-install tsx scripts/test/seed-local.ts .wrangler/e2e
exec npx --no-install wrangler dev --local -c wrangler.e2e.jsonc --persist-to .wrangler/e2e --ip 127.0.0.1 --port "$port"
import { spawnSync } from "node:child_process";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";

import { describe, expect, it } from "vitest";

import { migrationsDirectory } from "./migrate-sql";

const script = path.join(process.cwd(), "scripts", "test", "d1-migrations-check.sh");

function run(args: string[] = []) {
  return spawnSync("bash", [script, ...args], { encoding: "utf8", timeout: 120_000 });
}

describe("scripts/test/d1-migrations-check.sh (D1's own SQL limits, via wrangler --local)", () => {
  it("passes on the real migrations", () => {
    const r = run();
    expect(r.stderr).not.toContain("FAILED");
    expect(r.status).toBe(0);
  }, 120_000);

  it("fails on a migration with a 9-term compound SELECT (regression for 0043; libsql accepts it, D1 does not)", () => {
    const dir = fs.mkdtempSync(path.join(os.tmpdir(), "kate-mig-"));
    try {
      for (const f of fs.readdirSync(migrationsDirectory()).filter((n) => n.endsWith(".sql"))) {
        fs.copyFileSync(path.join(migrationsDirectory(), f), path.join(dir, f));
      }
      const terms = Array.from({ length: 9 }, (_, i) => `SELECT ${i + 1}`).join(" UNION ALL ");
      fs.writeFileSync(path.join(dir, "9999_nine_term_select.sql"), `INSERT INTO rate_limits (key, window_start, count) SELECT 'x', 1, 1 FROM (${terms});\n`);
      const r = run(["--migrations-dir", dir]);
      expect(r.status).toBe(1);
      expect(r.stderr).toContain("too many terms in compound SELECT");
    } finally {
      fs.rmSync(dir, { recursive: true, force: true });
    }
  }, 120_000);
});
