/// Debug-only launch hooks for the XCUITest target (UITests/). Compiled out of Release, so shipping builds
/// carry none of it. Active only when the app is launched with `-KATE_UITEST`:
///   -KATE_UITEST                 turn the hooks on
///   -KATE_UITEST_SERVER <url>    point the app at the fixture server (Tests/fixtures-server)
///   -KATE_UITEST_TOKEN <token>   start signed in with this session token (the fixture server accepts any)
/// Animations are switched off. The app's own `Date()` is not injectable app-wide (that would touch production code
/// everywhere), so UI tests assert fixed fixture text, never "N minutes ago".
@MainActor
enum TestHooks {
    private static var isActive: Bool { ProcessInfo.processInfo.arguments.contains("-KATE_UITEST") }

    private static func value(after flag: String) -> String? {
        let args = ProcessInfo.processInfo.arguments
        guard let i = args.firstIndex(of: flag), args.indices.contains(i + 1) else { return nil }
        return args[i + 1]
    }

    static func applyAtLaunch() {
        guard isActive else { return }
        UIView.setAnimationsEnabled(false)
        if let raw = value(after: "-KATE_UITEST_SERVER"), let url = URL(string: raw) {
            ServerStore.shared.set(url)
        }
        if let token = value(after: "-KATE_UITEST_TOKEN") {
            AuthStore.shared.establish(token: token, user: AuthUser(id: "u-sam", displayName: "Sam Seed"))
        }
    }
}
