import { sql } from "drizzle-orm";

import { safeEqual, sha256Hex } from "../auth/crypto";
import type { Database } from "../db/types";

export const TRIAGE_COOKIE = "kate_triage";
export const TRIAGE_COOKIE_MAX_AGE = 60 * 60 * 24 * 30;

/** The Worker secret that unlocks the triage page. Unset means the page is always a 404 and unlock always refuses. */
export function triageKey(): string | undefined {
  return process.env.KATE_TRIAGE_KEY?.trim() || undefined;
}

/** What the cookie holds: a digest of the key, so the raw secret never sits in the browser. */
const cookieValueFor = (key: string) => sha256Hex(`kate-triage-cookie:${key}`);

/** Constant-time check of a submitted key. With no key configured the compare still runs (against nothing) and always fails. */
export async function checkTriageKey(provided: unknown): Promise<boolean> {
  const key = triageKey();
  const equal = await safeEqual(typeof provided === "string" ? provided : "", key ?? "");
  return Boolean(key) && typeof provided === "string" && equal;
}

/** The value to set in the cookie after a correct key, or null when the key is wrong or unset. */
export async function triageCookieFor(provided: unknown): Promise<string | null> {
  if (!(await checkTriageKey(provided))) return null;
  return cookieValueFor(triageKey()!);
}

/** True only when a key is configured and the cookie carries its digest. */
export async function hasTriageCookie(cookieValue: string | undefined | null): Promise<boolean> {
  const key = triageKey();
  const expected = key ? await cookieValueFor(key) : "";
  const equal = await safeEqual(cookieValue ?? "", expected);
  return Boolean(key) && Boolean(cookieValue) && equal;
}

export function cookieFromHeader(header: string | null, name: string): string | undefined {
  for (const part of (header ?? "").split(";")) {
    const i = part.indexOf("=");
    if (i > 0 && part.slice(0, i).trim() === name) return part.slice(i + 1).trim();
  }
  return undefined;
}

import { NextResponse } from "next/server";

import { getDb } from "@/lib/db/client";
import { getBasePath } from "@/lib/env";
import { ipHash, withinRateLimit } from "@/lib/invites/rate-limit";
import { TRIAGE_COOKIE, TRIAGE_COOKIE_MAX_AGE, triageCookieFor } from "@/lib/diagnostics/triage";

export const dynamic = "force-dynamic";

const UNLOCK_LIMIT = { limit: 10, windowSeconds: 3600 };

const notFound = () => new NextResponse(null, { status: 404, headers: { "X-Robots-Tag": "noindex, nofollow" } });

/** `curl -d key=... https://<host>/api/triage/unlock -c jar`. A wrong or missing key (or no KATE_TRIAGE_KEY) is a bare 404 with no cookie. */
export async function POST(request: Request) {
  // Per-IP throttle (10 an hour), counted before the key is checked; a throttled request looks like a wrong key.
  if (!(await withinRateLimit(await getDb(), "triage-unlock", await ipHash(request), UNLOCK_LIMIT))) return notFound();
  let provided: unknown;
  try {
    provided = (await request.formData()).get("key");
  } catch {
    provided = undefined;
  }
  const value = await triageCookieFor(provided);
  if (!value) return notFound();
  const res = new NextResponse(null, { status: 303, headers: { Location: `${getBasePath()}/triage`, "X-Robots-Tag": "noindex, nofollow" } });
  res.cookies.set(TRIAGE_COOKIE, value, {
    httpOnly: true,
    sameSite: "lax",
    secure: process.env.NODE_ENV === "production",
    path: getBasePath() || "/",
    maxAge: TRIAGE_COOKIE_MAX_AGE,
  });
  return res;
}
