// Grafana is also routed by Docker labels in the main compose file; any label
// router for the observe host must carry the same tailnet-only middleware.
func TestGrafanaComposeLabelRouterIsTailnetOnly(t *testing.T) {
	raw, err := os.ReadFile(filepath.Join(dockerDir(t), "docker-compose.yml"))
	if err != nil {
		t.Fatal(err)
	}
	src := string(raw)
	hostRule := regexp.MustCompile("traefik\\.http\\.routers\\.([a-z0-9-]+)\\.rule=Host\\(`observe\\.")
	routers := hostRule.FindAllStringSubmatch(src, -1)
	if len(routers) == 0 {
		t.Skip("no Docker-label router for the observe host")
	}
	for _, m := range routers {
		want := "traefik.http.routers." + m[1] + ".middlewares=pace-tailnet-only@file"
		if !regexp.MustCompile(regexp.QuoteMeta(want)).MatchString(src) {
			t.Errorf("label router %q serves the observe host without pace-tailnet-only@file", m[1])
		}
	}
}
EOF
