import React, {useEffect} from 'react';
import {continueRender, delayRender, staticFile} from 'remotion';

/**
 * Loads the Pace brand faces (Mona Sans var + Monaspace Neon var, subset
 * woff2 in public/fonts) and blocks the render until document.fonts
 * reports them usable — no FOUT mid-film.
 */
export const Fonts: React.FC = () => {
  const [handle] = React.useState(() => delayRender('Loading brand fonts'));
  useEffect(() => {
    const css = `
      @font-face {
        font-family: 'Pace Mona Sans';
        src: url('${staticFile('fonts/mona-sans-var-latin.woff2')}') format('woff2');
        font-weight: 100 900;
        font-display: block;
      }
      @font-face {
        font-family: 'Pace Monaspace';
        src: url('${staticFile('fonts/monaspace-neon-var-latin.woff2')}') format('woff2');
        font-weight: 100 800;
        font-display: block;
      }
    `;
    const style = document.createElement('style');
    style.textContent = css;
    document.head.appendChild(style);
    document.fonts.ready.then(() => continueRender(handle));
    return () => {
      document.head.removeChild(style);
    };
  }, [handle]);
  return null;
};
