1	// Command tenant-stackd is the per-tenant stack node agent (plan KTD4/U3/U4).
2	// It polls tenant_stacks for this node, renders and applies each company's
3	// compose project through docker, health-checks it and writes status back.
4	// Nothing connects inbound to the node. See docs/ops/tenant-stackd.md.
5	package main
6	
7	import (
8		"context"
9		"flag"
10		"fmt"
11		"io"
12		"log/slog"
13		"os"
14		"os/signal"
15		"syscall"
16		"time"
17	
18		"github.com/duketopceo/pace-server/internal/db"
19		"github.com/duketopceo/pace-server/internal/tenantstack"
20	)
21	
22	func main() {
23		ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
24		defer stop()
25		os.Exit(run(ctx, os.Args[1:], os.Getenv, os.Stderr))
26	}
27	
28	func envOr(getenv func(string) string, k, def string) string {
29		if v := getenv(k); v != "" {
30			return v
31		}
32		return def
33	}
34	
35	func parseConfig(args []string, getenv func(string) string, errw io.Writer) (tenantstack.Config, error) {
36		fs := flag.NewFlagSet("tenant-stackd", flag.ContinueOnError)
37		fs.SetOutput(errw)
38		var c tenantstack.Config
39		fs.StringVar(&c.Node, "node", getenv("PACE_TENANT_NODE"), "node name matching tenant_stacks.node (env PACE_TENANT_NODE)")
40		fs.StringVar(&c.BaseDir, "base-dir", envOr(getenv, "PACE_TENANT_BASE_DIR", "/srv/pace-tenants"), "per-tenant state dir")
41		fs.StringVar(&c.Domain, "apps-domain", envOr(getenv, "PACE_APPS_DOMAIN", "pacehq-apps.com"), "apps domain")
42		fs.StringVar(&c.TraefikContainer, "traefik-container", envOr(getenv, "PACE_TENANT_TRAEFIK_CONTAINER", "traefik"), "node Traefik container to attach to each tenant edge network")
43		fs.DurationVar(&c.PollInterval, "poll-interval", 0, "poll interval (default 15s)")
44		if err := fs.Parse(args); err != nil {
45			return c, err
46		}
47		if v := getenv("PACE_TENANT_POLL_INTERVAL"); v != "" && c.PollInterval == 0 {
48			d, err := time.ParseDuration(v)
49			if err != nil {
50				return c, fmt.Errorf("PACE_TENANT_POLL_INTERVAL: %w", err)
51			}
52			c.PollInterval = d
53		}
54		// DSN only from env so it never shows in the process list.
55		c.DSN = getenv("TENANT_STACKD_DATABASE_URL")
56		c = c.WithDefaults()
57		if err := c.Validate(); err != nil {
58			return c, err
59		}
60		if c.DSN == "" {
61			return c, fmt.Errorf("TENANT_STACKD_DATABASE_URL is required")
62		}
63		return c, nil
64	}
65	
66	func run(ctx context.Context, args []string, getenv func(string) string, errw io.Writer) int {
67		cfg, err := parseConfig(args, getenv, errw)
68		if err != nil {
69			fmt.Fprintln(errw, "tenant-stackd:", err)
70			return 2
71		}
72		log := slog.New(slog.NewTextHandler(errw, nil))
73		pool, err := db.NewPool(ctx, cfg.DSN)
74		if err != nil {
75			fmt.Fprintln(errw, "tenant-stackd: database:", err)
76			return 1
77		}
78		defer pool.Close()
79		a := &tenantstack.Agent{
80			Cfg: cfg, Store: tenantstack.PGStore{DB: pool}, Runner: tenantstack.DockerRunner{}, Log: log,
81		}
82		log.Info("tenant-stackd started", "node", cfg.Node, "base_dir", cfg.BaseDir, "poll", cfg.PollInterval.String())
83		a.Run(ctx)
84		log.Info("tenant-stackd stopped")
85		return 0
86	}
