func (d DockerRunner) ComposeExec(ctx context.Context, project, file, envFile, service string, env map[string]string, stdin string, cmd ...string) ([]byte, error) {
	args := composeArgs(project, file, envFile, "exec", "-T", "-w", "/app")
	keys := make([]string, 0, len(env))
	for k := range env {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	for _, k := range keys {
		args = append(args, "-e", k+"="+env[k])
	}
	args = append(args, service)
	args = append(args, cmd...)
	return d.runIn(ctx, stdin, args...)
}
