func (p *FilesProvisioner) bucketExists(ctx context.Context, bucketID string) (exists bool, isPublic bool, err error) {
	resp, err := p.client.Get(ctx, "/storage/v1/bucket/"+bucketID)
	if err != nil {
		return false, false, err
	}
	defer resp.Body.Close()

	if IsNotFound(resp.StatusCode) {
		return false, false, nil
	}
	if resp.StatusCode != http.StatusOK {
		// Limit response body to 1MB to prevent memory exhaustion.
		body, _ := io.ReadAll(io.LimitReader(resp.Body, 1*1024*1024))
		return false, false, fmt.Errorf("get bucket %s returned %d: %s", bucketID, resp.StatusCode, string(body))
	}

	var bucket struct {
		Public bool `json:"public"`
	}
	// Limit response body to 1MB to prevent memory exhaustion.
	if err := json.NewDecoder(io.LimitReader(resp.Body, 1*1024*1024)).Decode(&bucket); err != nil {
		return false, false, fmt.Errorf("decode bucket response: %w", err)
	}

	return true, bucket.Public, nil
}

