// Service admin APIs must never be followed through a redirect: an SSO gate in
// front of Chatwoot's platform API answered 302 -> Authentik, Go followed it to
// a 200 login page, the provisioner read that as "account created", and the
// custom api_access_token header went along to the other host (2026-10-23).
func TestProvisioningClient_DoesNotFollowRedirects(t *testing.T) {
	var leaked bool
	idp := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.Header.Get("api_access_token") != "" {
			leaked = true
		}
		w.WriteHeader(http.StatusOK)
		_, _ = w.Write([]byte("<html>login</html>"))
	}))
	defer idp.Close()
	app := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		http.Redirect(w, r, idp.URL+"/authorize", http.StatusFound)
	}))
	defer app.Close()

	c := NewProvisioningClient(app.URL).WithAPIKey("platform-secret", "api_access_token")
	for _, call := range []func() (*http.Response, error){
		func() (*http.Response, error) { return c.Get(context.Background(), "/platform/api/v1/accounts") },
		func() (*http.Response, error) {
			return c.Post(context.Background(), "/platform/api/v1/accounts", map[string]string{"name": "x"})
		},
	} {
		resp, err := call()
		if err != nil {
			t.Fatalf("redirect must surface as a response, got error %v", err)
		}
		resp.Body.Close()
		if resp.StatusCode != http.StatusFound {
			t.Fatalf("status %d, want the 302 itself (not the followed page)", resp.StatusCode)
		}
	}
	if leaked {
		t.Fatal("credential header was sent to the redirect target")
	}
}
