// netList reads a compose service's networks in either form compose accepts:
// a list of names, or a map of name -> options (used where a service needs
// aliases). Tests only care about the names.
type netList []string

func (n *netList) UnmarshalYAML(v *yaml.Node) error {
	if v.Kind == yaml.SequenceNode {
		var l []string
		if err := v.Decode(&l); err != nil {
			return err
		}
		*n = l
		return nil
	}
	var m map[string]any
	if err := v.Decode(&m); err != nil {
		return err
	}
	out := make([]string, 0, len(m))
	for k := range m {
		out = append(out, k)
	}
	sort.Strings(out)
	*n = out
	return nil
}
