// StackMemberExecer is the subset of a pool or tx the member helpers need.
type StackMemberExecer interface {
	Exec(ctx context.Context, sql string, arguments ...any) (pgconn.CommandTag, error)
}

// StackMemberUpsertSQL queues 'pending' rows for the tenant_users row
// (tenant, email), for the apps in that tenant's stack. With no tenant_stacks
// row yet it inserts nothing; StackUpsertSQL backfills when the stack is created.
const StackMemberUpsertSQL = `
INSERT INTO tenant_stack_members (tenant_id, app, user_id, email, role, state)
SELECT tu.tenant_id, a.app, tu.id, tu.email, tu.role, 'pending'
FROM tenant_stacks ts CROSS JOIN LATERAL unnest(ts.apps) AS a(app)
JOIN tenant_users tu ON tu.tenant_id = ts.tenant_id
WHERE ts.tenant_id = $1::uuid AND lower(tu.email) = lower($2)
ON CONFLICT (tenant_id, app, user_id) DO UPDATE
SET email = EXCLUDED.email,
    role = EXCLUDED.role,
    state = CASE WHEN tenant_stack_members.state = 'removed' THEN 'pending' ELSE tenant_stack_members.state END,
    updated_at = now()`

// UpsertStackMember queues the member's stack accounts (see StackMemberUpsertSQL).
// A previously 'removed' row goes back to 'pending'; other states are kept. Call
// it after the tenant_users insert. Not flag-gated: see SyncStackMember.
func UpsertStackMember(ctx context.Context, db StackMemberExecer, tenantID, email string) error {
	_, err := db.Exec(ctx, StackMemberUpsertSQL, tenantID, email)
	return err
}

// MarkStackMemberRemoved marks the email's non-owner/admin stack rows
// 'removed' (tenant-stackd disables the account; nothing is deleted).
func MarkStackMemberRemoved(ctx context.Context, db StackMemberExecer, tenantID, email string) error {
	_, err := db.Exec(ctx, `
UPDATE tenant_stack_members SET state = 'removed', updated_at = now()
WHERE tenant_id = $1::uuid AND lower(email) = lower($2) AND role = 'member' AND state <> 'removed'`,
		tenantID, email)
	return err
}

