func makeReprovisionTenantHandler(pool reprovisionDB) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		// Limit request body to 1MB to prevent memory exhaustion/DoS.
		r.Body = http.MaxBytesReader(w, r.Body, 1*1024*1024)

		tenantID := chi.URLParam(r, "id")
		if len(tenantID) > 50 {
			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "tenant id too long (max 50 chars)"})
			return
		}
		if !uuidRe.MatchString(tenantID) {
			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "invalid tenant id"})
			return
		}

		if pool == nil {
			http.Error(w, "database not configured", http.StatusServiceUnavailable)
			return
		}

		var slug, plan string
		err := pool.QueryRow(r.Context(),
			`select slug, coalesce(plan,'') from tenants where id = $1::uuid`, tenantID,
		).Scan(&slug, &plan)
		if err != nil {
			writeJSON(w, http.StatusNotFound, map[string]string{"error": "tenant not found"})
			return
		}

		// Reuse the tenant's latest subscription so event rows converge on the
		// same key the webhook used. Empty is fine for never-billed tenants.
		var subscriptionID string
		_ = pool.QueryRow(r.Context(), `
			select subscription_id from tenant_provisioning_events
			where tenant_id = $1 order by updated_at desc limit 1
		`, tenantID).Scan(&subscriptionID)

		orch := provisioning.NewOrchestratorWith(pool)
		provErr := orch.ProvisionTenant(r.Context(), tenantID, slug, plan, subscriptionID)

		rows, qerr := pool.Query(r.Context(), `
			select service, status, coalesce(error,'') from tenant_provisioning_events
			where tenant_id = $1 order by service
		`, tenantID)
		if qerr != nil {
			slog.Error("reprovision: read events", "error", qerr, "tenant_id", tenantID)
			http.Error(w, "internal error", http.StatusInternalServerError)
			return
		}
		defer rows.Close()
		var services []map[string]string
		for rows.Next() {
			var svc, st, e string
			if err := rows.Scan(&svc, &st, &e); err != nil {
				continue
			}
			m := map[string]string{"service": svc, "status": st}
			if e != "" {
				m["error"] = e
			}
			services = append(services, m)
		}

		slog.Info("reprovision completed", "tenant_id", tenantID, "slug", slug, "plan", plan)
		if provErr != nil {
			writeJSON(w, http.StatusBadGateway, map[string]any{
				"error":    provErr.Error(),
				"services": services,
			})
			return
		}
