// anyArg is a convenience alias for pgxmock.AnyArg().
var anyArg = pgxmock.AnyArg()

// newMockPool creates a pgxmock pool or fatals the test.
func newMockPool(t *testing.T) pgxmock.PgxPoolIface {
	t.Helper()
	mock, err := pgxmock.NewPool()
	if err != nil {
		t.Fatalf("pgxmock.NewPool: %v", err)
	}
	return mock
}

// expectProvisionServiceCycle registers pgxmock expectations for one successful
// service provisioning: INSERT started, SELECT status, UPDATE ready, INSERT audit_log.
func expectProvisionServiceCycle(mock pgxmock.PgxPoolIface) {
	mock.ExpectExec("INSERT INTO tenant_provisioning_events").
		WithArgs(anyArg, anyArg, anyArg).
		WillReturnResult(pgxmock.NewResult("INSERT", 1))
	mock.ExpectQuery("SELECT status FROM tenant_provisioning_events").
		WithArgs(anyArg, anyArg, anyArg).
		WillReturnRows(pgxmock.NewRows([]string{"status"}).AddRow("started"))
	mock.ExpectExec("UPDATE tenant_provisioning_events").
		WithArgs(anyArg, anyArg, anyArg).
		WillReturnResult(pgxmock.NewResult("UPDATE", 1))
	mock.ExpectExec("INSERT INTO audit_log").
		WithArgs(anyArg, anyArg).
		WillReturnResult(pgxmock.NewResult("INSERT", 1))
}

// TestProvisionTenant_OperatePlan_FiveServices verifies Operate includes Core five
