// TestProvisionTenant_Idempotent verifies webhook replay skips Provision when
// events are already ready (early-exit; does not re-run provisioners).
func TestProvisionTenant_Idempotent(t *testing.T) {
	os.Setenv("PACE_PROVISION_STUB", "true")
	os.Setenv("PACE_DOMAIN", "pacehq.io")

	mock := newMockPool(t)
	defer mock.Close()

	tenantID := uuid.New().String()
	subID := "sub_idempotent_003"

	// Operate Core five: INSERT conflict + status already ready → skip Provision.
	for range 6 {
		mock.ExpectExec("INSERT INTO tenant_provisioning_events").
			WithArgs(anyArg, anyArg, anyArg).
			WillReturnResult(pgxmock.NewResult("INSERT", 0))
		mock.ExpectQuery("SELECT status FROM tenant_provisioning_events").
			WithArgs(anyArg, anyArg, anyArg).
			WillReturnRows(pgxmock.NewRows([]string{"status"}).AddRow("ready"))
	}
	mock.ExpectExec("UPDATE tenants").
		WithArgs(anyArg, anyArg).
		WillReturnResult(pgxmock.NewResult("UPDATE", 1))

	orch := provisioning.NewOrchestratorWith(mock)
	if err := orch.ProvisionTenant(context.Background(), tenantID, "acme", "operate", subID); err != nil {
		t.Fatalf("expected nil error on idempotent replay, got: %v", err)
	}
	if err := mock.ExpectationsWereMet(); err != nil {
		t.Fatalf("unmet expectations: %v", err)
	}
}

