// ssoLabels renders, for one app, the scrub and forward-auth middlewares and
// the ungated outpost router. Returns "" with SSO off. The result starts with
// a newline so it can follow the last label of the app directly.
func ssoLabels(d tmplData, app string) string {
	if !d.SSO {
		return ""
	}
	host := d.Hosts[app]
	scrub := "traefik.http.middlewares." + d.Project + "-" + app + "-scrub"
	sso := "traefik.http.middlewares." + d.Project + "-" + app + "-sso"
	out := "traefik.http.routers." + d.Project + "-" + app + "-outpost"
	var b strings.Builder
	for _, h := range ssoScrubHeaders {
		fmt.Fprintf(&b, "\n      - \"%s.headers.customrequestheaders.%s=\"", scrub, h)
	}
	fmt.Fprintf(&b, "\n      - \"%s.forwardauth.address=https://%s%sauth/traefik\"", sso, host, ssoOutpostPath)
	fmt.Fprintf(&b, "\n      - \"%s.forwardauth.trustForwardHeader=true\"", sso)
	fmt.Fprintf(&b, "\n      - \"%s.forwardauth.authResponseHeaders=%s\"", sso, strings.Join(ssoScrubHeaders, ","))
	fmt.Fprintf(&b, "\n      - \"%s.rule=Host(`%s`) && PathPrefix(`%s`)\"", out, host, ssoOutpostPath)
	fmt.Fprintf(&b, "\n      - \"%s.entrypoints=%s\"", out, d.EdgeEntrypoint)
	if d.EdgeTLS {
		fmt.Fprintf(&b, "\n      - \"%s.tls=true\"", out)
	}
	fmt.Fprintf(&b, "\n      - \"%s.priority=100\"", out)
	fmt.Fprintf(&b, "\n      - \"%s.service=%s\"", out, SSOOutpostService)
	return b.String()
}

