export function appById(id: string): PaceApp | undefined {
  return APPS.find((a) => a.id === id)
}

/** True when the catalog marks this app as not yet built (no app host / native page). */
export function isNotShipped(app: PaceApp): boolean {
  const catalog = APPS.find((a) => a.id === app.id)
  if (catalog == null) return false
  if (catalog.edgeRouted === false) return true
  // Apps with a host are "shipped codepaths" — the edge may still be down.
  if (catalog.hostApp) return false
  // Internal React pages and ops surfaces are always "shipped".
  if (catalog.tier === 'internal' || catalog.tier === 'ops') return false
  return !catalog.available
}

/**
 * True when an app must not be shown or launched for this caller (U36 / R7):
 * its isolation is none and the caller is not a platform operator.
 */
export function isHiddenFromTenant(app: PaceApp, email: string | undefined | null): boolean {
  return app.isolation === 'none' && !isPlatformOperator(email)
}

/**
 * The apps a tenant caller may see. External tenants lose isolation-none apps;
 * platform operators (dogfood) keep them, flagged `preview`.
 */
export function appsForTenant(apps: PaceApp[], email: string | undefined | null): PaceApp[] {
  const operator = isPlatformOperator(email)
  const out: PaceApp[] = []
  for (const app of apps) {
    if (app.isolation !== 'none') out.push(app)
    else if (operator) out.push({ ...app, preview: true })
  }
  return out
}

