/**
 * Apps every per-company stack serves (tenantstack.SupportedApps): PER_TENANT_APPS
 * plus Files (host <slug>-files) and Search (internal Meilisearch behind Strut).
 */
export const STACK_APP_IDS: readonly string[] = [...PER_TENANT_APPS, 'files', 'search']

/**
 * Catalog entry as it reads with per-company stacks on/off. With stacks on, a
 * stack app has its own instance per company: isolation-none becomes per-tenant
 * (mirrors entitlements.EffectiveIsolation), Files gets its host and Search its
 * command-bar page. Stacks off returns the app untouched.
 */
export function withStackCatalog(app: PaceApp, stacksOn: boolean = tenantStacksEnabled()): PaceApp {
  if (!stacksOn || !STACK_APP_IDS.includes(app.id)) return app
  const next: PaceApp = { ...app }
  if (next.isolation === 'none') next.isolation = 'per-tenant'
  if (app.id === 'files' || app.id === 'search') {
    next.available = true
    if (app.id === 'files') delete next.edgeRouted
  }
  return next
}

/** Catalog lookup that respects the stack overlay. */
export function catalogApp(id: string): PaceApp | undefined {
  const app = APPS.find((a) => a.id === id)
  return app && withStackCatalog(app)
}

