// RevokeUserSessions ends every Pace ID (Authentik) browser session of a user,
// so a removed member loses SSO to every app without waiting for the session
// to expire. It returns how many sessions were deleted.
//
// Authentik API (core -> authenticated_sessions):
//
//	GET    /api/v3/core/authenticated_sessions/?user__username=<name>
//	DELETE /api/v3/core/authenticated_sessions/{uuid}/
//
// See https://docs.goauthentik.io/ (API reference, "core" authenticated
// sessions). Because an unrecognised query filter is silently ignored by the
// server, every row is checked against userPK before it is deleted: a filter
// mismatch can never end another user's session.
func (c *AdminClient) RevokeUserSessions(ctx context.Context, userPK int, username string) (int, error) {
	if !c.Enabled() {
		return 0, errors.New("paceid: admin client not configured")
	}
	if userPK == 0 {
		return 0, errors.New("paceid: user pk required")
	}
	var victims []string
	page := 1
	for i := 0; ; i++ {
		if i >= maxListPages {
			return 0, fmt.Errorf("paceid: session list exceeded %d pages", maxListPages)
		}
		q := url.Values{"page_size": {"100"}, "page": {strconv.Itoa(page)}}
		if username != "" {
			q.Set("user__username", username)
		}
		var listed sessionPage
		if err := c.doJSON(ctx, http.MethodGet, "/api/v3/core/authenticated_sessions/?"+q.Encode(), nil, &listed); err != nil {
			return 0, err
		}
		for _, s := range listed.Results {
			if s.User == userPK && s.UUID != "" {
				victims = append(victims, s.UUID)
			}
		}
		if listed.Pagination.Next <= page {
			break
		}
		page = listed.Pagination.Next
	}
	n := 0
	for _, id := range victims {
		err := c.doJSON(ctx, http.MethodDelete, "/api/v3/core/authenticated_sessions/"+url.PathEscape(id)+"/", nil, nil)
		if err != nil && !IsNotFound(err) {
			return n, err
		}
		n++
	}
	return n, nil
}

