// RemoveMember takes the user out of the tenant group, which closes the SSO
// gate for that company's apps. Missing user or group is a no-op.
func (c *AdminClient) RemoveMember(ctx context.Context, email, tenantID string) error {
	if !c.Enabled() {
		return errors.New("paceid: admin client not configured")
	}
	email = strings.ToLower(strings.TrimSpace(email))
	if email == "" || strings.TrimSpace(tenantID) == "" {
		return errors.New("paceid: email and tenant_id required")
	}
	u, err := c.findUserByEmail(ctx, email)
	if err != nil || u == nil {
		return err
	}
	if err := c.RemoveUserFromGroup(ctx, tenantID, u.PK); err != nil {
		return err
	}
	// The gate now refuses the next request; ending the live sessions makes the
	// removal immediate for apps that already hold a session cookie (R7).
	return c.revokeSessions(ctx, u)
}

