// StackStatusPath is the member-scoped stack status endpoint (any signed-in
// member of the company, not admin-gated: every member's tiles read it).
const StackStatusPath = "/api/v1/stack/status"

// StackStatusResponse is the company's per-company stack as the portal sees it.
// State folds tenant_stacks.status: pending/applying read as "building" (the
// agent writes ready/failed only when a build ends), ready and failed pass
// through, stopped stays stopped. Health is the per-app flag from the last
// build outcome; last_error is never exposed.
type StackStatusResponse struct {
	Present bool            `json:"present"`
	State   string          `json:"state,omitempty"`
	Apps    []string        `json:"apps,omitempty"`
	Health  map[string]bool `json:"health,omitempty"`
