// fakeEntitlementsDB is a stateful in-memory stand-in for tenant_entitlements.
// It honours the column order of Store.Upsert (args 0-9, optional 10 =
// last_event_at) and answers Store reads by scanning into whatever dest types
// the caller passes, so it stays valid as the select list evolves.
type fakeEntitlementsDB struct {
	row     *fakeEntRow
	upserts int
	// staleUpsert makes the upsert a no-op that reports 0 rows affected, like
	// the SQL last_event_at guard does for a racing older event.
	staleUpsert bool
	// mu guards every field: the concurrent-delivery test drives the handler
	// from several goroutines.
	mu sync.Mutex
	// failDelete makes the compensating `delete from stripe_events` fail.
	failDelete bool
	// events models committed stripe_events rows; inflight holds ids inserted
	// by an open transaction, closed when it commits or rolls back. A second
	// insert of an in-flight id blocks on it, like Postgres' primary key does.
	events   map[string]bool
	inflight map[string]chan struct{}
}

// Begin opens a fake event transaction over the same in-memory state.
func (f *fakeEntitlementsDB) Begin(context.Context) (pgx.Tx, error) {
	return &fakeTx{db: f}, nil
}

type fakeTx struct {
	pgx.Tx
	db       *fakeEntitlementsDB
	inserted []string
	done     bool
}

// claimEvent inserts id like `on conflict do nothing` against a primary key:
// false when a committed row exists (after waiting out any open claim).
func (t *fakeTx) claimEvent(id string) bool {
	f := t.db
	for {
		f.mu.Lock()
		if f.events == nil {
			f.events = map[string]bool{}
			f.inflight = map[string]chan struct{}{}
		}
		if f.events[id] {
			f.mu.Unlock()
			return false
		}
		ch, busy := f.inflight[id]
		if !busy {
			f.inflight[id] = make(chan struct{})
			f.mu.Unlock()
			t.inserted = append(t.inserted, id)
			return true
		}
		f.mu.Unlock()
		<-ch
	}
}

func (t *fakeTx) release(commit bool) {
	if t.done {
		return
	}
	t.done = true
	f := t.db
	f.mu.Lock()
	defer f.mu.Unlock()
	for _, id := range t.inserted {
		if commit {
			f.events[id] = true
		}
		close(f.inflight[id])
		delete(f.inflight, id)
	}
}

func (t *fakeTx) Exec(ctx context.Context, sql string, args ...any) (pgconn.CommandTag, error) {
	if strings.Contains(sql, "stripe_events") && strings.Contains(sql, "insert into") {
		if t.claimEvent(args[0].(string)) {
			return pgconn.NewCommandTag("INSERT 0 1"), nil
		}
		return pgconn.NewCommandTag("INSERT 0 0"), nil
	}
	return t.db.Exec(ctx, sql, args...)
}

func (t *fakeTx) QueryRow(ctx context.Context, sql string, args ...any) pgx.Row {
	return t.db.QueryRow(ctx, sql, args...)
}

func (t *fakeTx) Commit(context.Context) error   { t.release(true); return nil }
func (t *fakeTx) Rollback(context.Context) error { t.release(false); return nil }

