func TestWebhook_StaleSubscriptionEventIgnored(t *testing.T) {
	stripeinternal.RegisterPriceID("price_ord_operate", "operate")
	const base = int64(1_800_000_000)

	type step struct {
		evtType, sub, status string
		created              int64
	}
	cases := []struct {
		name       string
		steps      []step
		wantSub    string
		wantStatus string
	}{
		{
			name: "retried delete of old sub does not cancel new sub",
			steps: []step{
				{"customer.subscription.created", "sub_A", "active", base + 1},
				{"customer.subscription.deleted", "sub_A", "canceled", base + 2},
				{"customer.subscription.created", "sub_B", "active", base + 3},
				{"customer.subscription.deleted", "sub_A", "canceled", base + 2}, // Stripe retry
			},
			wantSub: "sub_B", wantStatus: "active",
		},
		{
			name: "old-sub delete with identical timestamps is blocked by sub id alone",
			steps: []step{
				{"customer.subscription.created", "sub_A", "active", base},
				{"customer.subscription.deleted", "sub_A", "canceled", base},
				{"customer.subscription.created", "sub_B", "active", base},
				{"customer.subscription.deleted", "sub_A", "canceled", base},
			},
			wantSub: "sub_B", wantStatus: "active",
		},
		{
			name: "old-sub update after replacement is ignored",
			steps: []step{
				{"customer.subscription.created", "sub_A", "active", base + 1},
				{"customer.subscription.deleted", "sub_A", "canceled", base + 2},
				{"customer.subscription.created", "sub_B", "active", base + 3},
				{"customer.subscription.updated", "sub_A", "past_due", base},
			},
			wantSub: "sub_B", wantStatus: "active",
		},
		{
			name: "retried older update does not re-grant after delete",
			steps: []step{
				{"customer.subscription.updated", "sub_A", "active", base + 1},
				{"customer.subscription.deleted", "sub_A", "canceled", base + 2},
				{"customer.subscription.updated", "sub_A", "active", base + 1}, // Stripe retry
			},
			wantSub: "sub_A", wantStatus: "canceled",
		},
		{
			name: "new subscription after cancel is accepted",
			steps: []step{
				{"customer.subscription.created", "sub_A", "active", base + 1},
				{"customer.subscription.deleted", "sub_A", "canceled", base + 2},
				{"customer.subscription.created", "sub_B", "active", base + 3},
			},
			wantSub: "sub_B", wantStatus: "active",
		},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			db := &fakeEntitlementsDB{}
			h := newOrderingHandler(db)
			for i, s := range tc.steps {
				id := fmt.Sprintf("evt_%d", i)
				if code := postSubEvent(t, h, id, s.evtType, s.sub, s.status, s.created); code != http.StatusOK {
					t.Fatalf("step %d (%s %s): status %d", i, s.evtType, s.sub, code)
				}
			}
			if db.row == nil {
				t.Fatal("no entitlement row written")
			}
			if db.row.subID != tc.wantSub || db.row.status != tc.wantStatus {
				t.Fatalf("final row = sub %q status %q; want sub %q status %q",
					db.row.subID, db.row.status, tc.wantSub, tc.wantStatus)
			}
		})
	}
}

