/**
 * Build Authentik OAuth2 authorize URL (authorization code + S256 PKCE).
 * `VITE_AUTHENTIK_ISSUER` should be the provider issuer, e.g.
 * `https://id.pacehq.io/application/o/pace/` (authorize → `…/authorize/`).
 */
export async function buildAuthentikAuthorizeUrl(state?: string): Promise<string> {
  const issuer = (import.meta.env.VITE_AUTHENTIK_ISSUER ?? '').trim().replace(/\/$/, '')
  const clientId = import.meta.env.VITE_AUTHENTIK_CLIENT_ID ?? 'pace-strut'
  const redirectUri =
    import.meta.env.VITE_AUTHENTIK_REDIRECT_URI ??
    `${window.location.origin}/authenticate?provider=authentik`

  if (!issuer) {
    throw new Error('VITE_AUTHENTIK_ISSUER is required')
  }

  const started = await beginAuthentikLogin()
  const resolvedState = state ?? started.state
  if (state) {
    sessionStorage.setItem(OAUTH_STATE_KEY, state)
  }

  const authEndpoint = `${issuer}/authorize/`
  const u = new URL(authEndpoint)
  u.searchParams.set('client_id', clientId)
  u.searchParams.set('redirect_uri', redirectUri)
  u.searchParams.set('response_type', 'code')
  u.searchParams.set('scope', 'openid email profile groups pace')
  u.searchParams.set('state', resolvedState)
  u.searchParams.set('nonce', started.nonce)
  u.searchParams.set('code_challenge', started.codeChallenge)
  u.searchParams.set('code_challenge_method', 'S256')
  return u.toString()
}
