// QEMU may crash), or point the test at a Formbricks you run yourself with
// BROKER_CONTRACT_FORMBRICKS_URL, _PSQL (a command that reads SQL on stdin
// against its database) and _RESTART (a command that restarts it).
func TestBrokerFormbricksContract(t *testing.T) {
	st := startFormbricks(t)
	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Minute)
