	var adoption []members.AdoptionReport
	restarts := 0
	syn := &members.FormbricksSyncer{API: api, SQL: st.SQL, Creds: creds, OrgName: "Acme Co",
		Restart: func(context.Context) error { restarts++; return st.restart() },
		Report:  func(r members.AdoptionReport) { adoption = append(adoption, r) },
		Log:     slog.New(slog.NewTextHandler(io.Discard, nil))}
